INSERT INTO documentation_pages (title,slug,description,content,seo_title,meta_description,status,sort_order) VALUES
('Google Merchant Center feed setup','google-merchant','Generate, validate and connect the WooFeeds Pro RSS XML feed to Google Merchant Center.','<h2>Prepare the catalog</h2><p>Map brand, GTIN and MPN from the WooCommerce fields or attributes already used by the store. Add a Google product category when it is known.</p><ol><li>Open WooCommerce → WooFeeds Pro → Field Mapping.</li><li>Choose the source for brand, GTIN and MPN.</li><li>Run validation and correct important missing fields.</li></ol><h2>Generate the Google feed</h2><p>Enable Google Merchant, choose the target country and regenerate the feed. WooFeeds Pro publishes a completed RSS 2.0 XML snapshot at a stable URL.</p><h2>Connect Merchant Center</h2><p>Create a scheduled data source in Merchant Center and paste the Google feed URL. Match Google’s fetch schedule to the refresh interval selected in WooFeeds Pro.</p>','Google Merchant Center feed setup','Generate, validate and connect WooFeeds Pro to Google Merchant Center.','published',10),
('Meta Commerce catalog setup','meta-commerce','Connect WooFeeds Pro to a Meta Commerce Manager catalog with a scheduled data source.','<h2>Map Meta-ready fields</h2><p>Use stable product IDs, absolute HTTPS links, current prices, images and accurate availability. Add Google and Facebook product categories where useful.</p><h2>Publish the Meta feed</h2><p>Enable Meta Commerce and generate the catalog XML. Variable products can be exported as separate items while sharing a product group.</p><h2>Schedule the catalog</h2><p>In Commerce Manager, choose a data feed as the source, paste the hosted Meta URL and schedule recurring updates.</p>','Meta Commerce catalog setup','Connect WooFeeds Pro to Meta Commerce Manager with a scheduled catalog feed.','published',20),
('ChatGPT product feed setup','chatgpt','Configure and publish the WooFeeds Pro compressed JSONL product feed for ChatGPT commerce.','<h2>Configure seller details</h2><p>Enter the seller name, target countries and required catalog mappings. Keep product URLs and image URLs publicly reachable over HTTPS.</p><h2>Generate JSONL.gz</h2><p>WooFeeds Pro writes one normalized product object per line, then compresses the completed catalog with gzip.</p><h2>Validate before submission</h2><p>Review the plain-language validation report for missing titles, prices, images, availability, identifiers and country targeting.</p>','ChatGPT product feed setup','Configure and publish a compressed WooFeeds Pro JSONL product feed.','published',30),
('Licensing and domain migration','licensing','Activate a domain-locked WooFeeds Pro license and move it safely between stores.','<h2>Activate once</h2><p>The first successful activation locks the license to the normalized store domain. A key cannot activate on a second domain while the original activation remains active.</p><h2>Offline grace</h2><p>License validation is cached. A temporary licensing-service outage can enter the configured grace period without deleting completed feed files.</p><h2>Move a store</h2><p>Deactivate the license on the old domain, complete the migration, then activate the same key on the new domain.</p>','Licensing and domain migration','Activate and migrate a domain-locked WooFeeds Pro license.','published',40),
('Troubleshooting WooFeeds Pro','troubleshooting','Fix common feed generation, mapping, cron, licensing and channel-import problems.','<h2>Feed is not refreshing</h2><p>Check the last-run time on the dashboard. If WordPress traffic is low or WP-Cron is disabled, run the WooFeeds WP-CLI command from a real server cron.</p><h2>Products are missing identifiers</h2><p>Confirm the GTIN, MPN and brand mappings. The validator reports exactly how many catalog items are affected.</p><h2>Channel rejects an image</h2><p>Use an absolute HTTPS image URL that is publicly reachable and not blocked by authentication or robots rules.</p><h2>License shows another domain</h2><p>Deactivate the previous domain before activating on the new one. Contact support if the old store is no longer accessible.</p>','Troubleshooting WooFeeds Pro','Fix common WooFeeds Pro feed, mapping, cron and licensing problems.','published',50)
